require "rails_helper"

RSpec.describe InvoiceOperationsRecord, committed_data: true do
  def count_intents_elsewhere(operation_id)
    Thread.new do
      ActiveRecord::Base.connection_pool.with_connection do |connection|
        connection.select_value(
          "SELECT count(*) FROM invoice_operation_intents WHERE company_id = 1 AND operation_id = '#{operation_id}'"
        )
      end
    end.value
  end

  # "Write the pending intent (`invoice_operation_intents`) in its own transaction before prepare."
  it "commits an intent written on its own connection while an invoice transaction is open and keeps it after that transaction rolls back" do
    operation_id = SecureRandom.uuid

    expect(InvoiceOperationsRecord.connection).not_to equal(ApplicationRecord.connection)

    ApplicationRecord.transaction do
      InvoiceOperationsRecord.transaction do
        InvoiceOperationsRecord.connection.execute(<<~SQL)
          INSERT INTO invoice_operation_intents (company_id, invoice_id, operation_id, state, generation, created_at)
          VALUES (1, 10, '#{operation_id}', 'pending', 1, now())
        SQL
      end

      expect(count_intents_elsewhere(operation_id)).to eq(1)
      raise ActiveRecord::Rollback
    end

    expect(count_intents_elsewhere(operation_id)).to eq(1)
  end
end
